//! HTML generated by javadoc: the generator comment and the date metadata.
//!
//! A file is javadoc output when its first 1024 bytes hold `<!-- Generated by javadoc`.
//! Only its head is rewritten, its first 15 lines up to the first holding `</head>`
//! (letter case aside): in each, `<!-- Generated by javadoc ... -->`
//! (from the first such comment to the last ` -->` of the line) is removed, and a line
//! left with nothing but whitespace is removed with it; the content of every
//! `<meta name="date" content="...">` and `<meta name="dc.created" content="...">`
//! (letter case aside) becomes the timestamp's date; a line with neither holding
//! `<html lang="...">` becomes `<html>`. A file in which any of these matched is
//! rewritten, even if the result is the same.

use crate::time::Utc;

const MARKER: &[u8] = b"<!-- Generated by javadoc";
const COMMENT: &[u8] = b"<!-- Generated by javadoc ";
const LINES: usize = 15;

/// Whether `data` is javadoc output.
#[must_use]
pub fn detect(data: &[u8]) -> bool {
    let head = data.get(..data.len().min(1024)).unwrap_or_default();
    find(head, MARKER).is_some()
}

fn find(hay: &[u8], needle: &[u8]) -> Option<usize> {
    hay.windows(needle.len()).position(|w| w == needle)
}

/// The line without its generator comment, if it has one.
fn strip_comment(line: &[u8]) -> Option<Vec<u8>> {
    let start = find(line, COMMENT)?;
    // `.+ -->`: at least one character, then the last ` -->` on the line
    let from = start.checked_add(COMMENT.len())?.checked_add(1)?;
    let tail = line.get(from..)?;
    let end = tail.windows(4).rposition(|w| w == b" -->")?;
    let end = from.checked_add(end)?.checked_add(4)?;
    let mut out = line.get(..start)?.to_vec();
    out.extend_from_slice(line.get(end..)?);
    Some(out)
}

/// Replace the content of the date metadata; whether any matched.
fn dates(line: &mut Vec<u8>, date: &[u8]) -> bool {
    let mut matched = false;
    for name in [&b"date"[..], b"dc.created"] {
        let mut prefix = b"<meta name=\"".to_vec();
        prefix.extend_from_slice(name);
        prefix.extend_from_slice(b"\" content=\"");
        let mut pos = 0;
        while let Some(at) = line.get(pos..).and_then(|rest| {
            rest.windows(prefix.len())
                .position(|w| w.eq_ignore_ascii_case(&prefix))
        }) {
            let content = pos.saturating_add(at).saturating_add(prefix.len());
            let Some(close) = line
                .get(content..)
                .and_then(|rest| rest.iter().position(|&b| b == b'"'))
            else {
                break;
            };
            let close = content.saturating_add(close);
            if line.get(close..close.saturating_add(2)) != Some(&b"\">"[..]) {
                pos = content;
                continue;
            }
            line.splice(content..close, date.iter().copied());
            matched = true;
            pos = content.saturating_add(date.len()).saturating_add(2);
        }
    }
    matched
}

/// Whether the line holds `<html lang="...">`, a language given.
fn html_lang(line: &[u8]) -> bool {
    let tag = b"<html lang=\"";
    let mut pos = 0;
    while let Some(at) = line.get(pos..).and_then(|rest| find(rest, tag)) {
        let value = pos.saturating_add(at).saturating_add(tag.len());
        let rest = line.get(value..).unwrap_or_default();
        if let Some(close) = rest.iter().position(|&b| b == b'"')
            && close > 0
            && rest.get(close..close.saturating_add(2)) == Some(&b"\">"[..])
        {
            return true;
        }
        pos = value;
    }
    false
}

/// The normalized file, or `None` when it is not javadoc output or nothing matched.
#[must_use]
pub fn normalize(data: &[u8], time: i64) -> Option<Vec<u8>> {
    if !detect(data) {
        return None;
    }
    let u = Utc::from_unix(time);
    // the year unpadded, as strip-nondeterminism writes it
    let day = format!("{}-{:02}-{:02}", u.year, u.month, u.day);
    let mut out = Vec::with_capacity(data.len());
    let mut matched = false;
    let mut rest = data;
    for _ in 0..LINES {
        if rest.is_empty() {
            break;
        }
        let n = rest
            .iter()
            .position(|&b| b == b'\n')
            .map_or(rest.len(), |n| n.saturating_add(1));
        let (line, tail) = rest.split_at(n);
        rest = tail;
        let mut line = line.to_vec();
        if let Some(stripped) = strip_comment(&line) {
            matched = true;
            // white space: space, \t, \n, \v, \f, \r
            if stripped
                .iter()
                .all(|b| matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r'))
            {
                continue;
            }
            line = stripped;
        }
        let head_end = line.windows(7).any(|w| w.eq_ignore_ascii_case(b"</head>"));
        if dates(&mut line, day.as_bytes()) {
            matched = true;
        } else if html_lang(&line) {
            matched = true;
            line = b"<html>\n".to_vec();
        }
        out.extend_from_slice(&line);
        if head_end {
            break;
        }
    }
    out.extend_from_slice(rest);
    matched.then_some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    const T: i64 = 1_767_225_600;

    fn n(s: &str) -> Option<String> {
        normalize(s.as_bytes(), T).map(|v| String::from_utf8(v).unwrap())
    }

    #[test]
    fn comment_lines() {
        let c = "<!-- Generated by javadoc (1.8.0) on Thu Jan 02 03:04:05 UTC 2030 -->";
        assert_eq!(
            n(&format!("{c}\n<html></html>\n")).unwrap(),
            "<html></html>\n"
        );
        assert_eq!(n(&format!("x {c}\ny\n")).unwrap(), "x \ny\n");
        assert_eq!(n(&format!("{c} y\nz\n")).unwrap(), " y\nz\n");
        assert_eq!(n(&format!("\t{c}  \r\nz\n")).unwrap(), "z\n");
        assert_eq!(n(&format!("{c} {c}\nz\n")).unwrap(), "z\n");
        assert_eq!(n(&format!("a\n\n  {c}\nz\n")).unwrap(), "a\n\nz\n");
        assert_eq!(n(c).unwrap(), "");
        // the comment needs text between `javadoc ` and ` -->`
        assert_eq!(n("<!-- Generated by javadoc -->\nx\n"), None);
        assert_eq!(
            n("<!-- Generated by javadoc -- and more -->\nx\n").unwrap(),
            "x\n"
        );
    }

    #[test]
    fn window() {
        let c = "<!-- Generated by javadoc (1) -->";
        let at = |line: usize| format!("{}{c}\nx\n", "a\n".repeat(line - 1));
        assert!(n(&at(15)).is_some());
        assert_eq!(n(&at(16)), None);
        let at_byte = |b: usize| format!("{}\n{c}\nx\n", "y".repeat(b - 1));
        assert!(n(&at_byte(999)).is_some());
        assert_eq!(n(&at_byte(1000)), None);
    }

    #[test]
    fn meta_dates() {
        let m = "<!-- Generated by javadoc -->\n<META NAME=\"date\" CONTENT=\"2030-01-02T03:04\">\
                 <meta name=\"dc.created\" content=\"\">\n<meta  name=\"date\" content=\"x\">\n\
                 <meta name=\"date\" content=\"x\"/>\n";
        assert_eq!(
            n(m).unwrap(),
            "<!-- Generated by javadoc -->\n<META NAME=\"date\" CONTENT=\"2026-01-01\">\
             <meta name=\"dc.created\" content=\"2026-01-01\">\n<meta  name=\"date\" content=\"x\">\n\
             <meta name=\"date\" content=\"x\"/>\n"
        );
        assert!(
            n("<!-- Generated by javadoc -->\n<meta name=\"date\" content=\"2026-01-01\">\n")
                .is_some()
        );
        assert_eq!(
            n("<html>\n<meta name=\"date\" content=\"2030-01-02\">\n"),
            None
        );
    }
}
